///////////////////////////////////\n\nmodel Company {\n  id          String   @id @default(cuid())\n  name        String\n  email       String   @unique\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  jobs Job[]\n}\n\nenum JobType {\n  INTERNSHIP\n  FULL_TIME\n}\n\nenum JobLevel {\n  JUNIOR\n  MID\n  SENIOR\n}\n\nmodel Job {\n  id    String @id @default(cuid())\n  title String\n\n  company   Company @relation(fields: [companyId], references: [id])\n  companyId String\n\n  location String\n  type     JobType\n  role     JobRole\n  level    JobLevel\n  tags     String\n  salary   String?\n\n  description      String\n  responsibilities String\n  requirements     String\n  benefits         String?\n\n  createdAt DateTime @default(now())\n\n  applications Application[]\n}\n\n//////////////////////////////////////////////////////\n// Module 3 - Question Bank\n//////////////////////////////////////////////////////\n\nenum JobRole {\n  SOFTWARE_ENGINEER\n  UX_ENGINEER\n  PROJECT_MANAGER\n}\n\nenum QuestionType {\n  MCQ\n  SCENARIO\n}\n\nenum Difficulty {\n  EASY\n  MEDIUM\n  HARD\n}\n\nmodel Question {\n  id          String       @id @default(cuid())\n  role        JobRole\n  topic       String\n  type        QuestionType\n  difficulty  Difficulty\n  prompt      String\n  explanation String?\n  createdAt   DateTime     @default(now())\n\n  options    Option[]\n  correctKey String?\n  rubric     String?\n\n  examAnswers ExamAnswer[]\n\n  @@index([role, difficulty, topic])\n}\n\nmodel Option {\n  id         String @id @default(cuid())\n  questionId String\n  key        String\n  text       String\n\n  question Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n\n  @@unique([questionId, key])\n}\n\n//////////////////////////////////////////////////////\n// Module 3 - Application System\n//////////////////////////////////////////////////////\n\nmodel Application {\n  id        String   @id @default(cuid())\n  jobId     String\n  role      JobRole\n  createdAt DateTime @default(now())\n\n  fullName  String\n  email     String\n  mobile    String?\n  linkedin  String?\n  github    String?\n  portfolio String?\n\n  university     String\n  degree         String\n  specialization String?\n  cgpa           String?\n  awards         String?\n\n  programmingLanguages String\n  frameworks           String?\n  softwareProficiency  String?\n\n  job Job @relation(fields: [jobId], references: [id], onDelete: Cascade)\n\n  projects    Project[]\n  scenarios   ScenarioAnswer[]\n  examAnswers ExamAnswer[] // ✅ REQUIRED reverse relation\n  violations  ExamViolation[]\n\n  lockedQuestions Json?\n  examSubmitted   Boolean @default(false)\n\n  @@index([jobId])\n}\n\nmodel Project {\n  id            String @id @default(cuid())\n  applicationId String\n  name          String\n  details       String\n\n  application Application @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n}\n\nmodel ScenarioAnswer {\n  id            String @id @default(cuid())\n  applicationId String\n  questionKey   String\n  answer        String\n\n  application Application @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n}\n\nmodel ExamAnswer {\n  id            String   @id @default(cuid())\n  questionId    String\n  applicationId String\n  answer        String?\n  createdAt     DateTime @default(now())\n\n  question    Question    @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  application Application @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n\n  @@index([questionId])\n  @@index([applicationId])\n}\n\nmodel ExamViolation {\n  id            String        @id @default(cuid())\n  applicationId String\n  type          ViolationType\n  message       String\n  createdAt     DateTime      @default(now())\n\n  application Application @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n\n  @@index([applicationId])\n}\n\nenum ViolationType {\n  FULLSCREEN_EXIT\n  TAB_SWITCH\n  COPY_PASTE_RIGHTCLICK\n  SCREENSHOT_ATTEMPT\n  DEV_TOOLS\n}\n",
